import{_ as t,o as n,c as o,ae as i}from"./chunks/framework.sRTLHEzD.js";const u=JSON.parse('{"title":"Use voice input across panes","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/voice_input_across_panes.md","filePath":"documentation/voice_input_across_panes.md"}'),a={name:"documentation/voice_input_across_panes.md"};function s(r,e,c,h,d,p){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="use-voice-input-across-panes" tabindex="-1">Use voice input across panes <a class="header-anchor" href="#use-voice-input-across-panes" aria-label="Permalink to &quot;Use voice input across panes&quot;">​</a></h1><p>Record speech in one composition bar and keep its resulting text there while you work in other panes.</p><h2 id="start-voice-input" tabindex="-1">Start voice input <a class="header-anchor" href="#start-voice-input" aria-label="Permalink to &quot;Start voice input&quot;">​</a></h2><p>First enable <strong>Enable voice input</strong> in the <strong>Voice input</strong> section of Settings. Open the composition bar where the spoken text should go. Hold its push-to-talk button while speaking, then release the button to stop recording; a short click starts recording until you click the button again.</p><h2 id="continue-working-while-speech-is-processed" tabindex="-1">Continue working while speech is processed <a class="header-anchor" href="#continue-working-while-speech-is-processed" aria-label="Permalink to &quot;Continue working while speech is processed&quot;">​</a></h2><p>You can switch tabs or workspaces while recording or while speech is being changed into text. The recording and resulting text stay with the composition bar that started the recording.</p><p>Only one composition bar can use the microphone at a time. A red microphone on the recording tab and workspace identifies where recording is active; return to that tab to stop it. If you start voice input in another composition bar while one is recording, the first recording continues and a notice names its tab and workspace.</p><h2 id="send-or-cancel-the-recording" tabindex="-1">Send or cancel the recording <a class="header-anchor" href="#send-or-cancel-the-recording" aria-label="Permalink to &quot;Send or cancel the recording&quot;">​</a></h2><p>Select <strong>Send</strong> or press Enter in the composition bar to wait for its speech text and send the images and text together. To cancel recording, waiting, or transcription, select the small <strong>X</strong> beside the level bars; cancellation leaves the existing text and images in place.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun_code/documentation/send_images_with_the_composition_bar.html">Send images with the composition bar</a>: add images and text to one pane.</li><li><a href="/heidrun_code/documentation/settings.html">Change Heidrun Code settings</a>: find the Voice input settings.</li></ul>',11)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
